cat >> classic/apps/electron/test/agent-computer.test.js <<'EOF'

test("a revocation while the enable dialog is open cannot revive computer access",async t=>{
 let resolve,opened;
 const shown=new Promise(r=>{opened=r;});
 const f=await fixture(t,{confirm:()=>{opened();return new Promise(r=>{resolve=r;});}});
 const pending=f.service.setAccess({...scope,enabled:true});await shown;f.service.revoke();resolve(true);
 assert.deepEqual(await pending,{enabled:false});await assert.rejects(f.execute({type:"list",path:f.dir}),/off/);
});

test("UTF-8 chunk boundaries and old receipts survive cancellation without redoing writes",async t=>{
 const f=await fixture(t);await f.service.setAccess({...scope,enabled:true});
 const file=path.join(f.dir,"unicode.txt"),text="א".repeat(3000)+"end";
 const op={type:"write",path:file,content:text,expectedSha256:null};
 const receipt=await f.execute(op,"unicode");
 const first=JSON.parse((await f.execute({type:"read",path:file,offset:0},"chunk1")).text);
 const second=JSON.parse((await f.execute({type:"read",path:file,offset:first.nextOffset},"chunk2")).text);
 assert.equal(first.text+second.text,text);assert.equal(first.sha256,second.sha256);
 f.service.revoke();assert.deepEqual(await f.execute(op,"unicode"),receipt);assert.equal(f.prompts.length,2);
});
EOF
node classic/node_modules/prettier/bin/prettier.cjs --write classic/apps/electron/test/agent-computer.test.js
node --test classic/apps/electron/test/agent-computer.test.js
